# Examine rule from demo1: input colors 1 (two comps), 6 (three comps)
# output: color6 comps at left, color1 comps at right? Actually col0-1 = 6s, then 1s at cols2-4.
# Look at each color's components in input and their arrangement in output.
def comps_of(g,color):
    H=len(g);W=len(g[0]);seen=set();out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x]==color and (y,x) not in seen:
                st=[(y,x)];cs=[];seen.add((y,x))
                while st:
                    a,b=st.pop();cs.append((a,b))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=a+dy,b+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==color and (ny,nx) not in seen:
                            seen.add((ny,nx));st.append((ny,nx))
                out.append(sorted(cs))
    return out
